        TransparentPanel panel = (TransparentPanel) this._activity.findViewById(R.id.banner_panel);
        DisplayMetrics dm = new DisplayMetrics();
        this._activity.getWindowManager().getDefaultDisplay().getMetrics(dm);
        if (dm.widthPixels < this._width + 6) {
            panel.getLayoutParams().width = dm.widthPixels;
            float relation = (((dm.widthPixels - 6) / this._width) * this._height) + 6.0f;
            panel.getLayoutParams().height = (int) relation;
