        this._activity.findViewById(R.id.banner_webkit).setVisibility(8);
        AdView adView = _replaceAdMobView(publisherId);
        adView.setVisibility(0);
        AdRequest request = new AdRequest();
        if (gender != null) {
            request.setGender(gender);
        }
        if (birthday != null) {
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
            try {
                request.setBirthday(dateFormat.parse(birthday));
            } catch (ParseException e) {
                Log.e(AdRequest.LOGTAG, e.getMessage());
            }
        }
        if (keywords != null) {
            request.setKeywords(keywords);
        }
        if (latitude != null && longtitude != null) {
            Location location = new Location("Appsgeyser");
            location.setLatitude(latitude.doubleValue());
            location.setLongitude(longtitude.doubleValue());
            request.setLocation(location);
        }
        adView.loadAd(request);
    }

    private AdView _replaceAdMobView(String publisherId) {
        FrameLayout layout = (FrameLayout) this._activity.findViewById(R.id.ad_container);
        layout.removeView(this._activity.findViewById(AD_MOB_VIEW_ID));
        AdView view = new AdView(this._activity, AdSize.BANNER, publisherId);
        view.setId(AD_MOB_VIEW_ID);
        layout.addView(view);
        return view;
    }
