        WindowManager windowManager = (WindowManager) Factory.getInstance().getMainNavigationActivity().getSystemService("window");
        if (Build.VERSION.SDK_INT > 6) {
            dBrowserWidth = 10;
        } else {
            dBrowserWidth = 20;
        }
        System.out.println("dBrowserWidth = " + dBrowserWidth);
        int browserHeight = windowManager.getDefaultDisplay().getHeight() - 50;
        int browserWidth = windowManager.getDefaultDisplay().getWidth() - dBrowserWidth;
        float contentHeight = this._widgetInfo.getHeight() + 5;
        float contentWidth = this._widgetInfo.getWidth();
        float dH = browserHeight / (contentHeight + this._tabsPadding);
        float dW = browserWidth / contentWidth;
        if (dH > 1.0f && dW > 1.0f) {
            dScale = Math.min(dH, dW) * 100.0f;
        } else {
            dScale = Math.min(dH, dW) * 100.0f;
        }
        int scale = (int) dScale;
        return scale;
    }

    private int calculateScale(int contentHeight, int contentWidth) {
        int browserHeight = this._browser.getHeight();
        int browserWidth = this._browser.getWidth();
        float dH = browserHeight / contentHeight;
        float dW = browserWidth / contentWidth;
        float dScale = Math.min(dH, dW) * 100.0f;
        return (int) dScale;
    }

