    @Override // android.app.Activity
    protected void onPause() {
        super.onPause();
        KeyguardManager kgMgr = (KeyguardManager) getSystemService("keyguard");
        boolean showing = kgMgr.inKeyguardRestrictedInputMode();
        if (!showing && !this._config.getPreventFromSleep()) {
            BrowserWebView bannerBrowser = (BrowserWebView) findViewById(R.id.banner_webkit);
            if (bannerBrowser != null) {
                bannerBrowser.pauseTimers();
                callHiddenWebViewMethod("onPause", bannerBrowser);
            }
            if (this._tabsController != null) {
                this._tabsController.onPause();
            }
            CookieSyncManager.getInstance().stopSync();
        }
    }

    @Override // android.app.Activity
    protected void onResume() {
        super.onResume();
        if (!this._config.getPreventFromSleep()) {
            String regId = C2DMessaging.getRegistrationId(this);
            if (regId != null && !"".equals(regId)) {
                this._serverClient.SendRegisteredId(regId);
            } else {
                C2DMessaging.register(this, AppsGeyserServerClient.SENDER_ID);
            }
            BrowserWebView bannerBrowser = (BrowserWebView) findViewById(R.id.banner_webkit);
            if (bannerBrowser != null) {
                bannerBrowser.resumeTimers();
                callHiddenWebViewMethod("onResume", bannerBrowser);
            }
            if (this._tabsController != null) {
                this._tabsController.onResume();
            }
            CookieSyncManager.getInstance().startSync();
        }
    }

    private void callHiddenWebViewMethod(String name, WebView browser) {
        try {
            Method method = WebView.class.getMethod(name, new Class[0]);
            method.invoke(browser, new Object[0]);
        } catch (IllegalAccessException e) {
            Log.e("Illegal Access: " + name, e.getMessage());
        } catch (NoSuchMethodException e2) {
            Log.e("No such method: " + name, e2.getMessage());
        } catch (InvocationTargetException e3) {
            Log.e("Invocation Target Exception: " + name, e3.getMessage());
        }
    }

