    @Override // com.wBloodPressureSymptoms.ads.AdsLoader.HeadersReceiver
    public boolean onAdHeadersReceived(Map<String, List<String>> headers) {
        BehaviorFactory factory = new BehaviorFactory();
        List<BehaviorVisitor> preloadBehaviors = factory.createPreloadBehaviors(headers);
        _applyBehaviors(preloadBehaviors);
        SharedPreferences settings = getSharedPreferences(PREFS_NAME, 0);
        long sleepMsecs = settings.getLong(ADS_SLEEP_PARAM, 0L);
        Date now = new Date();
        Date sleepDate = new Date(sleepMsecs);
        return now.compareTo(sleepDate) >= 0;
    }

    @Override // com.wBloodPressureSymptoms.ads.AdsLoader.AdsLoadingFinishedListener
    public void onAdLoadFinished() {
        BehaviorFactory factory = new BehaviorFactory();
        List<BehaviorVisitor> postloadBehaviors = factory.createPostloadBehaviors(this.adsLoader.getLastResponseHeaders());
        _applyBehaviors(postloadBehaviors);
    }

    private void _applyBehaviors(List<BehaviorVisitor> behaviors) {
        for (BehaviorVisitor visitor : behaviors) {
            acceptBehavior(visitor);
            this.adsLoader.acceptBehavior(visitor);
            this.bannerLayout.acceptBehavior(visitor);
        }
    }

    @Override // com.wBloodPressureSymptoms.ads.behavior.BehaviorAcceptor
    public void acceptBehavior(BehaviorVisitor visitor) {
        visitor.visit(this);
    }
