    public void updateConfigurationXML(String xmlText) {
        String strUrl = "";
        int width = 0;
        int heigth = 0;
        int time = 0;
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            DocumentBuilder db = dbf.newDocumentBuilder();
            InputSource is = new InputSource();
            is.setCharacterStream(new StringReader(xmlText));
            Document doc = db.parse(is);
            NodeList nodes = doc.getElementsByTagName("banner");
            if (nodes.getLength() > 0) {
                Element element = (Element) nodes.item(0);
                NodeList currentNodeList = element.getElementsByTagName("url");
                Element paramElem = (Element) currentNodeList.item(0);
                strUrl = getCharacterDataFromElement(paramElem);
                NodeList currentNodeList2 = element.getElementsByTagName("time");
                Element paramElem2 = (Element) currentNodeList2.item(0);
                time = Integer.parseInt(getCharacterDataFromElement(paramElem2));
                NodeList currentNodeList3 = element.getElementsByTagName("height");
                Element paramElem3 = (Element) currentNodeList3.item(0);
                heigth = Integer.parseInt(getCharacterDataFromElement(paramElem3));
                NodeList currentNodeList4 = element.getElementsByTagName("width");
                Element paramElem4 = (Element) currentNodeList4.item(0);
                width = Integer.parseInt(getCharacterDataFromElement(paramElem4));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        this._startupScreenController.initializeBanner(strUrl, time, width, heigth);
    }

