    private void SendRequestAsync(final String requestURL, final RequestType type) {
        Thread t = new Thread() { // from class: com.wBloodPressureSymptoms.Server.AppsGeyserServerClient.2
            @Override // java.lang.Thread, java.lang.Runnable
            public void run() {
                try {
                    HttpClient client = new DefaultHttpClient(AppsGeyserServerClient.this.httpParameters);
                    HttpGet httpGet = new HttpGet(requestURL);
                    httpGet.setHeader("Cache-Control", "no-cache,no-store");
                    HttpResponse response = client.execute(httpGet);
                    if (type.ordinal() == RequestType.APPMODE.ordinal()) {
                        if (response.getStatusLine().getStatusCode() == AppsGeyserServerClient.OK_RESPONSE) {
                            AppsGeyserServerClient.this.mAppMode = MainNavigationActivity.ApplicationMode.CUSTOM;
                        } else if (response.getStatusLine().getStatusCode() == AppsGeyserServerClient.FORBIDDEN_RESPONSE) {
                            AppsGeyserServerClient.this.mAppMode = MainNavigationActivity.ApplicationMode.COMMON;
                        }
                        AppsGeyserServerClient.this._activity.runOnUiThread(new Runnable() { // from class: com.wBloodPressureSymptoms.Server.AppsGeyserServerClient.2.1
                            @Override // java.lang.Runnable
                            public void run() {
                                AppsGeyserServerClient.this._activity.setApplicationMode(AppsGeyserServerClient.this.mAppMode);
                            }
                        });
                    }
                    if (response.getStatusLine().getStatusCode() == AppsGeyserServerClient.OK_RESPONSE) {
                        if (type.ordinal() != RequestType.CONFIGURATION.ordinal()) {
                            AppsGeyserServerClient.this.handler.sendEmptyMessage(type.ordinal());
                            return;
                        }
                        Message msg = Message.obtain();
                        msg.what = type.ordinal();
                        msg.obj = response;
                        AppsGeyserServerClient.this.handler.sendMessage(msg);
                        return;
                    }
                    if (response.getStatusLine().getStatusCode() == AppsGeyserServerClient.FORBIDDEN_RESPONSE && type.ordinal() == RequestType.USAGE.ordinal()) {
                        AppsGeyserServerClient.this._activity.runOnUiThread(new Runnable() { // from class: com.wBloodPressureSymptoms.Server.AppsGeyserServerClient.2.2
                            @Override // java.lang.Runnable
                            public void run() {
                                AppsGeyserServerClient.this._activity.showPausedContentInfo();
                            }
                        });
                    } else if (type.ordinal() == RequestType.REGISTER_ID.ordinal()) {
                        C2DMessaging.clearRegistrationId(AppsGeyserServerClient.this._activity);
                    } else {
                        AppsGeyserServerClient.this.handler.sendEmptyMessage(-1);
                    }
                } catch (Exception e) {
                    AppsGeyserServerClient.this.handler.sendEmptyMessage(-2);
                }
            }
        };
        t.start();
    }

