public class AppNotificationManager {
    public static final int NOTIFICATION_ID = 10001;

    public static Intent getLaunchIntent(Context context, String title, String url) {
        Intent intent = new Intent(context, (Class<?>) MessageViewer.class);
        Bundle extras = new Bundle();
        extras.putString("url", url);
        extras.putString("title", title);
        intent.putExtras(extras);
        return intent;
    }

    public static void generateNotification(Context context, String msg, String title, Intent intent) {
        long when = System.currentTimeMillis();
        Notification notification = new Notification(R.drawable.icon, title, when);
        int iUniqueId = (int) (System.currentTimeMillis() & 268435455);
        notification.setLatestEventInfo(context, title, msg, PendingIntent.getActivity(context, iUniqueId, intent, 0));
        notification.flags |= 16;
        int notificatonID = (int) System.currentTimeMillis();
        NotificationManager nm = (NotificationManager) context.getSystemService("notification");
        nm.notify(notificatonID, notification);
        playNotificationSound(context);
    }

    public static void playNotificationSound(Context context) {
        Ringtone rt;
        Uri uri = RingtoneManager.getDefaultUri(2);
        if (uri != null && (rt = RingtoneManager.getRingtone(context, uri)) != null) {
            rt.setStreamType(5);
            rt.play();
        }
    }
}

